Same example as above:
Let's create a generalized file server in Node
`domain/file.html`
`domain/image.jpg`
`domain/file.json`:
1) Retrieve file name from request
2) set [[MME]] type based on extension
3) send file as response

Review the differences between: [[Package]] and [[Module]] 
`file-server.js`
```js
//You dont really have to write this kind of code,
const http = require("http");
const url  = require("url");
const path = require("path");
const fs   = require("fs");
const mimeTypes = [
	["ohtml", "text/html"],
	//...
]

const server = http.createServer((req, resp) => {
			//1. get the filename from the requested path
			 let requestFile = url.parse(req.url).pathname;
			 let filename    = path.join(process.cloud(), requestedFile);
				// We need an absolute filesystem path
				//process is a built in node object

			//2. Check if this file exists on the server
			fs.exists(filename, (exists) => {
				if (!exists) display404(req, resp);
				readAndReturn(fs, filename, req, resp);
			});

});
//Ideally you would put the port in a config file, but for now,
const port = 8080;
server.listen(port);
```

Probably in some other file:
```js
function display404(req, resp) {
	resp.writeHead(404, {"Content-Type" : "text/html"});
	resp.write("<html><h1>File not found, get fucked loser</h1></html");
	resp.end();
}
```

Probably in some even other-er file:
```js
function readAndReturn(fs, filename, req, resp) {
	//now we need to read the file
	//let's do it sys
	fs.readFile(filename, "binary", (err, file) => {
				if (err) { display500(resp) }
				else { 
					const mime = mimeTypes.find(m => 
						m[0] == path.parse(filename).ext)
					resp.writeHead(200, {"Content-Type" : mime[1]});
					resp.write(file); 
				}
	});
}
```

